static String[] repeated(String word, int n) {
    String[] out = new String[n];
    for (int i = 0; i < n; i++) {
        out[i] = word;
    }
    return out;
}

static int totalLength(String[] words) {
    int total = 0;
    for (int i = 0; i < words.length; i++) {
        if (words[i] != null) {
            total += words[i].length();
        }
    }
    return total;
}

static String firstNonNull(String[] words) {
    for (int i = 0; i < words.length; i++) {
        if (words[i] != null) {
            return words[i];
        }
    }
    return null;
}
